# build-plugin.sh - GENERATED by scripts/gen-build-plugin.ps1. Do not edit.
# Edit the sources under plugin/ and regenerate.
#
# Builds LaughTail 0.1.0 from source, on the host, in a throwaway maven container.
#
# Nothing is installed on the host: no JDK, no Maven. Never-break rule 13 and
# 33.2 item 4 both say not to, and OA-03 means there is no snapshot to recover
# from if a host package install went wrong.

set -e

SRC=/home/ubuntu/laughtail-plugin
M2=/home/ubuntu/.m2
IMAGE=maven:3.9-eclipse-temurin-25
VERSION=0.1.0
V=$(sudo -n ls -1 /var/lib/pelican/volumes | head -1)
D="/var/lib/pelican/volumes/$V"
OWN=999:987

echo "=== disk before (a maven cache is not small) ==="
df -h --output=avail,pcent / | tail -1

mkdir -p "$SRC" "$M2"
# Literal path, not "$SRC/target": the guard refuses a recursive delete whose
# target is a variable, because a static check cannot know what it expands to.
# Removes only generated output, never the sources written below.
sudo -n rm -rf /home/ubuntu/laughtail-plugin/target
# Ownership: maven used to run as root in the container, which left root-owned
# output that the ubuntu user then could not clear on the next build. It now runs
# as the host user (see the docker run below), so this only matters once.
sudo -n chown -R ubuntu:ubuntu /home/ubuntu/laughtail-plugin /home/ubuntu/.m2 2>/dev/null || true
mkdir -p "$SRC/src/main/java/gg/laughtail/core" "$SRC/src/main/resources"

# ---- pom.xml ----
cat > "$SRC/pom.xml" <<'LT_SRC_EOF_pom_xml'
<?xml version="1.0" encoding="UTF-8"?>
<!--
  LaughTail core plugin.

  This is the plugin Sections 3 to 16 live inside. Everything the server does that
  is not vanilla Minecraft happens here, so it is built from source in this
  repository rather than downloaded - never-break rule 9 is about pinning third
  party jars; this one we own.

  BUILD ENVIRONMENT. Compiled inside a throwaway `maven` container on the VPS, not
  with host packages. Same reasoning as decision D-0023 for MariaDB: never-break
  rule 13 and spec 33.2 item 4 say do not install host packages mid-build without a
  snapshot, and OA-03 means no snapshot exists. A container needs nothing on the
  host and leaves nothing behind.

  JAVA 25, and not by choice. Paper 26.2's API jar is compiled to class file major
  version 69, which IS Java 25 - a release 21 compile cannot even read it and
  javac reports every symbol as missing rather than naming the version. Measured:
  "class file has wrong version 69.0, should be 65.0". So Minecraft 26.x requires
  Java 25, the server already runs Temurin 25, and the plugin now matches.

  THE MARIADB DRIVER IS SHADED IN, deliberately. Paper's plugin.yml `libraries:`
  mechanism would keep the jar small but downloads from Maven Central on first load,
  which makes startup depend on the network and makes the installed bytes something
  other than the bytes that were built. Shading is deterministic. The cost is about
  half a megabyte.
-->
<project xmlns="http://maven.apache.org/POM/4.0.0"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd">
  <modelVersion>4.0.0</modelVersion>

  <groupId>gg.laughtail</groupId>
  <artifactId>laughtail-core</artifactId>
  <version>0.1.0</version>
  <packaging>jar</packaging>
  <name>LaughTail</name>

  <properties>
    <maven.compiler.release>25</maven.compiler.release>
    <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>
    <!-- Pinned. Never a floating version - spec 4.2.
         Paper changed its API coordinate scheme for the 26.x line: the artifact is
         26.2.build.<n>-stable, which pins the API to the EXACT server build rather
         than to a version-wide -R0.1-SNAPSHOT. That is strictly better for this
         project - API and server cannot drift apart - and it is why the first
         attempt at 26.2-R0.1-SNAPSHOT could not be resolved. -->
    <paper.api.version>26.2.build.119-stable</paper.api.version>
    <mariadb.driver.version>3.5.2</mariadb.driver.version>
  </properties>

  <repositories>
    <repository>
      <id>papermc</id>
      <url>https://repo.papermc.io/repository/maven-public/</url>
    </repository>
  </repositories>

  <dependencies>
    <dependency>
      <groupId>io.papermc.paper</groupId>
      <artifactId>paper-api</artifactId>
      <version>${paper.api.version}</version>
      <!-- provided: the server supplies it at runtime and it must NOT be shaded. -->
      <scope>provided</scope>
    </dependency>
    <dependency>
      <groupId>org.mariadb.jdbc</groupId>
      <artifactId>mariadb-java-client</artifactId>
      <version>${mariadb.driver.version}</version>
    </dependency>
  </dependencies>

  <build>
    <finalName>LaughTail-${project.version}</finalName>
    <resources>
      <resource>
        <directory>src/main/resources</directory>
        <filtering>true</filtering>
      </resource>
    </resources>
    <plugins>
      <plugin>
        <groupId>org.apache.maven.plugins</groupId>
        <artifactId>maven-shade-plugin</artifactId>
        <!-- 3.6.2, not 3.5.3. Shade rewrites bytecode with ASM, and 3.5.3's ASM
             cannot read Java 25 class files: it fails with
             "Unsupported class file major version 69" AFTER a successful compile,
             which looks like a shading bug and is really a toolchain version gap. -->
        <version>3.6.2</version>
        <executions>
          <execution>
            <phase>package</phase>
            <goals><goal>shade</goal></goals>
            <configuration>
              <createDependencyReducedPom>false</createDependencyReducedPom>
              <relocations>
                <!-- Relocated so this plugin's driver cannot collide with a driver
                     another plugin shades. Two copies of the same class in one
                     class loader is a real and confusing failure. -->
                <relocation>
                  <pattern>org.mariadb.jdbc</pattern>
                  <shadedPattern>gg.laughtail.libs.mariadb</shadedPattern>
                </relocation>
              </relocations>
              <transformers>
                <!--
                  Without this, relocation breaks JDBC discovery. The driver jar
                  ships META-INF/services/java.sql.Driver naming
                  org.mariadb.jdbc.Driver, and relocation moves the CLASS but leaves
                  that text file pointing at the old name - so DriverManager finds a
                  service entry for a class that no longer exists and reports
                  "No suitable driver found", which sounds like a connection problem
                  and is actually a packaging one.
                -->
                <transformer implementation="org.apache.maven.plugins.shade.resource.ServicesResourceTransformer"/>
              </transformers>
              <filters>
                <filter>
                  <artifact>*:*</artifact>
                  <excludes>
                    <exclude>META-INF/*.SF</exclude>
                    <exclude>META-INF/*.DSA</exclude>
                    <exclude>META-INF/*.RSA</exclude>
                    <exclude>module-info.class</exclude>
                  </excludes>
                </filter>
              </filters>
            </configuration>
          </execution>
        </executions>
      </plugin>
    </plugins>
  </build>
</project>
LT_SRC_EOF_pom_xml

# ---- src/main/resources/plugin.yml ----
cat > "$SRC/src/main/resources/plugin.yml" <<'LT_SRC_EOF_src_main_resources_plugin_yml'
name: LaughTail
version: '${project.version}'
main: gg.laughtail.core.LaughTailPlugin
api-version: '26.2'
author: LaughTail SMP
description: The LaughTail core. Access, rules gate, player registry.

# folia-supported is deliberately absent: this plugin is not Folia-safe and saying
# otherwise would let it load on a server it cannot run correctly on.

commands:
  laughtail:
    description: LaughTail administration. Never use vanilla /reload (never-break rule 7).
    usage: /laughtail <status|reload>
    aliases: [lt]
  rules:
    description: Read the rules, and accept them.
    usage: /rules [accept]
  # Moderation. Permission nodes come from the Section 17 ladder, so a Helper physically
  # cannot issue a permanent ban regardless of what the code does.
  warn:
    description: Warn a player. Recorded permanently.
    usage: /warn <player> <reason>
  mute:
    description: Mute a player for a duration.
    usage: /mute <player> <30m|2h|7d> <reason>
  unmute:
    description: Revoke an active mute.
    usage: /unmute <player> [reason]
  kick:
    description: Kick a player. Recorded permanently.
    usage: /kick <player> <reason>
  tempban:
    description: Temporarily ban a player.
    usage: /tempban <player> <30m|2h|7d> <reason>
  ban:
    description: Permanently ban a player.
    usage: /ban <player> <reason>
  unban:
    description: Overturn a ban.
    usage: /unban <player> [reason]
  access:
    description: Grant, revoke and audit paid access. The whitelist IS the paywall (17.3).
    usage: /access <grant|revoke|list|audit>
  season:
    description: Season lifecycle. Owner and Console only (17.3).
    usage: /season <status|start|end>
  history:
    description: View a player's punishment history. Viewing is itself audited.
    usage: /history <player>

permissions:
  # These mirror server/permissions.yml. LuckPerms is the source of truth for who
  # holds them; this block only declares they exist and their default.
  #
  # Every default is 'op' or 'false', never 'true'. A permission that defaults to
  # true is granted to everyone the moment the plugin loads, which would silently
  # bypass the Section 17 ladder that was so carefully built.
  laughtail.player.basic:
    description: Baseline player access.
    default: true          # the one deliberate exception: every paying player has it
  laughtail.rules.accept:
    description: Accept the rules.
    default: true          # a new player must be able to accept, or the gate traps them
  laughtail.reload:
    description: Reload LaughTail config. 17.2 grants this to Admin; reloading the SERVER is 17.3 and denied.
    default: op
  laughtail.status:
    description: View LaughTail status including database connectivity.
    default: op
  laughtail.rules.bypass:
    description: Bypass the rules gate. Console and Owner only - never staff.
    default: false
LT_SRC_EOF_src_main_resources_plugin_yml

# ---- src/main/resources/config.yml ----
cat > "$SRC/src/main/resources/config.yml" <<'LT_SRC_EOF_src_main_resources_config_yml'
# LaughTail core configuration.
#
# THE PASSWORD IS NOT IN THIS FILE AND MUST NEVER BE. It is written into the
# deployed copy on the host by scripts/remote/deploy-plugin-config.sh, which reads
# it from /home/ubuntu/laughtail-db/secrets/app_password - root-only, never printed,
# never committed (never-break rule 5, decision D-0014's pattern).
#
# NOTE FOR ANYONE EDITING THIS FILE: do not write the placeholder token into a
# comment. An earlier version of this header quoted it, the deploy script replaced
# EVERY occurrence, and the real password was substituted into the comment and then
# printed past a redaction that only masked the "password:" line. See D-0026. The
# substitution is now anchored to the password key alone, but the cheapest defence
# is simply not to repeat the token in prose.

database:
  # 127.0.0.1 because the db container publishes only on loopback (D-0023) and the
  # game container reaches the host through the docker bridge gateway. The deploy
  # script resolves the correct address for this host rather than guessing.
  host: '__DB_HOST__'
  port: 3306
  schema: laughtail
  user: laughtail
  password: '__PRESERVE__'

rules:
  # Bump this version whenever the text changes. Every player who accepted an older
  # version is re-gated automatically - that is the entire reason acceptance row 17
  # stores a version rather than a boolean.
  #
  # '0-draft' is deliberate and honest: the real rules text is owner action OA-13,
  # which also covers Terms, Privacy and Refund wording. The GATE is built and
  # tested; the words are not mine to write.
  version: '0-draft'
  text:
    - 'These rules are a DRAFT placeholder (owner action OA-13).'
    - ''
    - '1. No cheating. No hacked clients, no exploits, no duplication.'
    - '2. No griefing outside claimed combat. Rank comes from PvP only.'
    - '3. One account per person. Alt accounts do not earn rating.'
    - '4. No real-money trading of anything in game.'
    - '5. Treat other players decently. Harassment ends access.'
    - ''
    - 'The published version of these rules will be identical on the website,'
    - 'in game and in Discord (acceptance row 18).'
LT_SRC_EOF_src_main_resources_config_yml

# ---- src/main/java/gg/laughtail/core/LaughTailPlugin.java ----
cat > "$SRC/src/main/java/gg/laughtail/core/LaughTailPlugin.java" <<'LT_SRC_EOF_src_main_java_gg_laughtail_core_LaughTailPlugin_java'
package gg.laughtail.core;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.plugin.java.JavaPlugin;

import java.sql.SQLException;
import java.util.List;
import java.util.logging.Level;

/**
 * LaughTail core.
 *
 * Scope at 0.1.0, deliberately small and complete rather than broad and half-done
 * (standing bias: fewer features working perfectly):
 *
 *   - registers every joining player in the database, keyed on UUID
 *   - enforces the rules gate (acceptance row 17) with the accepted VERSION stored
 *   - /laughtail status, so the server can be asked whether it is actually healthy
 *   - /laughtail reload, which is what never-break rule 7 says to use instead of
 *     vanilla /reload
 *
 * NOT here yet, and not pretended: Berries, rank, seasons, shop, cosmetics, the 6.6
 * watchdog. Those are Phases 3 to 7 and several are blocked on owner decisions
 * (Q-10 economy numbers, OA-12 price).
 */
public final class LaughTailPlugin extends JavaPlugin implements Listener {

    private Database database;
    private RulesGate rulesGate;
    private WorldRules worldRules;
    private StatsTracker statsTracker;
    private CombatTracker combatTracker;
    private Moderation moderation;
    private AccessGrants accessGrants;
    private String rulesVersion;
    private List<String> rulesText;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        loadSettings();

        this.rulesGate = new RulesGate(this);
        this.worldRules = new WorldRules(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getPluginManager().registerEvents(rulesGate, this);
        getServer().getPluginManager().registerEvents(worldRules, this);

        // Section 7.2. Applied here rather than over RCON because a console /gamerule
        // reaches only the default world and `execute in <dim> run gamerule` is rejected
        // by the 26.2 parser. Also re-applied on WorldLoadEvent, so the resource world
        // (7.4) and arena (7.1) inherit these rules when they are eventually created.
        worldRules.applyToAll();

        // Stats and combat. Both write only through Database, which refuses main-thread
        // calls, so acceptance row 25 is enforced by the layer below rather than by these
        // classes remembering to be careful.
        this.statsTracker = new StatsTracker(this, database);
        this.combatTracker = new CombatTracker(this, database, statsTracker);
        loadPrivateThresholds();
        getServer().getPluginManager().registerEvents(statsTracker, this);
        getServer().getPluginManager().registerEvents(combatTracker, this);
        statsTracker.start();

        // Moderation. Every command path writes a staff_audit row, including the ones that
        // fail validation - an audit that records only successes is a record of intentions.
        this.moderation = new Moderation(this, database);
        this.accessGrants = new AccessGrants(this, database);
        getServer().getPluginManager().registerEvents(moderation, this);

        // Connectivity is checked ASYNCHRONOUSLY. Doing it here on the main thread
        // would block startup on a network timeout, and acceptance row 25 forbids
        // main-thread database work regardless of how convenient it is.
        getServer().getScheduler().runTaskAsynchronously(this, () -> {
            boolean ok = database.checkConnectivity();
            if (ok) {
                getLogger().info("Database reachable, migration V1 present.");
            } else {
                getLogger().severe("STARTING WITHOUT A WORKING DATABASE. "
                    + "Players will be gated and cannot be recorded. Fix the database, "
                    + "then /laughtail reload.");
            }
        });

        getLogger().info("LaughTail " + getPluginMeta().getVersion() + " enabled. Rules version "
            + rulesVersion + ".");
    }

    private void loadSettings() {
        FileConfiguration c = getConfig();
        this.rulesVersion = c.getString("rules.version", "0-draft");
        this.rulesText = c.getStringList("rules.text");
        if (rulesText.isEmpty()) {
            rulesText = List.of("The rules have not been written yet (owner action OA-13).");
        }
        this.database = new Database(
            this,
            c.getString("database.host", "127.0.0.1"),
            c.getInt("database.port", 3306),
            c.getString("database.schema", "laughtail"),
            c.getString("database.user", "laughtail"),
            c.getString("database.password", "")
        );
    }

    String rulesVersion() { return rulesVersion; }
    List<String> rulesText() { return rulesText; }

    /**
     * Loads the anti-farm thresholds from a PRIVATE file that is deliberately not part of
     * the plugin's committed config.
     *
     * Never-break rule 10: "Never publish detector thresholds for anti-cheat, wagering, or
     * market manipulation. Publishing them teaches evasion." A player who knows the
     * repeat-kill window is one hour and the limit is three knows exactly how to farm an
     * alt without ever being flagged.
     *
     * So `config.yml` - which is in git - contains none of these numbers, and
     * `private.yml` alongside it is created on the host, listed in .gitignore, and read
     * here. If it is absent the plugin still runs on conservative placeholders and says so
     * loudly, because silently running with unknown thresholds would be worse than either
     * alternative.
     */
    private void loadPrivateThresholds() {
        java.io.File f = new java.io.File(getDataFolder(), "private.yml");
        if (!f.isFile()) {
            combatTracker.configure(3_600_000L, 3, "", false);
            return;
        }
        org.bukkit.configuration.file.YamlConfiguration p =
            org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(f);
        long window = p.getLong("anti-farm.repeat-kill-window-seconds", 3600L) * 1000L;
        int limit = p.getInt("anti-farm.repeat-kills-before-zero", 3);
        String salt = p.getString("anti-farm.ip-hash-salt", "");
        if (salt == null || salt.isBlank()) {
            getLogger().warning("private.yml has no ip-hash-salt. Same-IP detection still "
                + "works, but unsalted hashes of the IPv4 space are reversible by brute force.");
        }
        combatTracker.configure(window, limit, salt, true);
        // The VALUES are never logged - only that they were loaded. Logging them would put
        // them in a file that gets pasted into support threads.
        getLogger().info("Anti-farm thresholds loaded from private.yml (values not logged).");
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        Player p = e.getPlayer();

        // Gate FIRST, release later if the database says they have accepted. The
        // safe default is gated: if the database is down, a player who has already
        // accepted is inconvenienced, whereas the opposite default would let an
        // unaccepted player straight in and quietly break row 17.
        if (!p.hasPermission("laughtail.rules.bypass")) {
            rulesGate.gate(p);
        }

        getServer().getScheduler().runTaskAsynchronously(this, () -> {
            try {
                String accepted = database.registerAndGetAcceptedRules(
                    p.getUniqueId(), p.getName());
                if (rulesVersion.equals(accepted)) {
                    getServer().getScheduler().runTask(this, () -> {
                        if (p.isOnline()) {
                            rulesGate.release(p);
                            p.sendMessage(Component.text("Welcome back to Laugh Tale.", NamedTextColor.GOLD));
                        }
                    });
                } else if (accepted != null) {
                    // Accepted an OLDER version. This is precisely why row 17 wants
                    // the version stored rather than a boolean.
                    getServer().getScheduler().runTask(this, () -> {
                        if (p.isOnline()) {
                            p.sendMessage(Component.text(
                                "The rules have changed since you last accepted them.",
                                NamedTextColor.YELLOW));
                        }
                    });
                }
            } catch (SQLException ex) {
                getLogger().log(Level.SEVERE,
                    "Could not record player " + p.getUniqueId() + ": " + ex.getMessage());
                getServer().getScheduler().runTask(this, () -> {
                    if (p.isOnline()) {
                        p.sendMessage(Component.text(
                            "The server could not reach its database. Staff have been notified.",
                            NamedTextColor.RED));
                    }
                });
            }
        });
    }

    @Override
    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {
        String name = cmd.getName().toLowerCase();

        if (moderation.handle(sender, name, args)) return true;
        if (name.equals("access")) return accessGrants.handle(sender, args);

        if (name.equals("rules")) {
            if (!(sender instanceof Player p)) {
                sender.sendMessage("Rules version " + rulesVersion);
                return true;
            }
            if (args.length == 0) {
                rulesGate.showRules(p);
                return true;
            }
            if (args[0].equalsIgnoreCase("accept")) {
                if (!p.hasPermission("laughtail.rules.accept")) {
                    p.sendMessage(Component.text("You cannot accept the rules.", NamedTextColor.RED));
                    return true;
                }
                if (!rulesGate.isGated(p)) {
                    p.sendMessage(Component.text("You have already accepted the current rules.",
                        NamedTextColor.GRAY));
                    return true;
                }
                final String version = rulesVersion;
                getServer().getScheduler().runTaskAsynchronously(this, () -> {
                    try {
                        database.recordRulesAcceptance(p.getUniqueId(), version);
                        getServer().getScheduler().runTask(this, () -> {
                            if (p.isOnline()) {
                                rulesGate.release(p);
                                p.sendMessage(Component.text(
                                    "Rules accepted (version " + version + "). Welcome to Laugh Tale.",
                                    NamedTextColor.GREEN));
                            }
                        });
                    } catch (SQLException ex) {
                        getLogger().log(Level.SEVERE, "Could not store rules acceptance: " + ex.getMessage());
                        getServer().getScheduler().runTask(this, () -> {
                            if (p.isOnline()) {
                                // NOT released. An acceptance that was not stored did
                                // not happen - releasing anyway would make row 17 a lie.
                                p.sendMessage(Component.text(
                                    "Could not save your acceptance. Please try again.",
                                    NamedTextColor.RED));
                            }
                        });
                    }
                });
                return true;
            }
            p.sendMessage(Component.text("Usage: /rules [accept]", NamedTextColor.GRAY));
            return true;
        }

        if (name.equals("season")) {
            // Season control is OWNER-ONLY by permission, and that is not a convenience:
            // 17.3 puts "season management, manual reset or manual Champion assignment" on
            // the never-grant-to-Admin list because "the integrity of the competition
            // depends on this being untouchable by staff".
            if (!sender.hasPermission("laughtail.season.reset")) {
                sender.sendMessage(Component.text(
                    "Season management is Owner and Console only (17.3).", NamedTextColor.RED));
                return true;
            }
            String sub = args.length > 0 ? args[0].toLowerCase() : "status";
            switch (sub) {
                case "status" -> getServer().getScheduler().runTaskAsynchronously(this, () -> {
                    try {
                        java.util.List<String> lines = database.seasonSummary();
                        int active = database.activeSeason();
                        getServer().getScheduler().runTask(this, () -> {
                            sender.sendMessage(Component.text("Seasons (active: "
                                + (active < 0 ? "none" : active) + ")", NamedTextColor.GOLD));
                            if (lines.isEmpty()) {
                                sender.sendMessage(Component.text("  no seasons yet - /season start",
                                    NamedTextColor.GRAY));
                            }
                            for (String l : lines) {
                                sender.sendMessage(Component.text("  " + l, NamedTextColor.GRAY));
                            }
                        });
                    } catch (SQLException e) {
                        getLogger().log(Level.SEVERE, "season status failed: " + e.getMessage());
                    }
                });
                case "start" -> {
                    // 31.1 makes seasons monthly. 30 days rather than a calendar month so
                    // every season is the same length - a February champion should not have
                    // had three fewer days than a March one.
                    final int days = 30;
                    getServer().getScheduler().runTaskAsynchronously(this, () -> {
                        try {
                            int n = database.startSeason(days);
                            database.audit(null, sender.getName(), "season.start", null, null,
                                n < 0 ? "refused - a season is already running" : "season " + n, null);
                            getServer().getScheduler().runTask(this, () -> sender.sendMessage(
                                Component.text(n < 0
                                    ? "Refused: a season is already active, in finale or resetting."
                                    : "Season " + n + " started, ending in " + days + " days.",
                                    n < 0 ? NamedTextColor.RED : NamedTextColor.GREEN)));
                        } catch (SQLException e) {
                            getLogger().log(Level.SEVERE, "season start failed: " + e.getMessage());
                        }
                    });
                }
                case "end" -> getServer().getScheduler().runTaskAsynchronously(this, () -> {
                    try {
                        int active = database.activeSeason();
                        if (active < 0) {
                            getServer().getScheduler().runTask(this, () -> sender.sendMessage(
                                Component.text("No active season.", NamedTextColor.RED)));
                            return;
                        }
                        String result = database.endSeason(active);
                        database.audit(null, sender.getName(), "season.end", null, null,
                            "season " + active + ": " + result, null);
                        getServer().getScheduler().runTask(this, () -> sender.sendMessage(
                            Component.text("Season " + active + ": " + result,
                                result.startsWith("REFUSED") ? NamedTextColor.RED : NamedTextColor.GREEN)));
                    } catch (SQLException e) {
                        getLogger().log(Level.SEVERE, "season end failed: " + e.getMessage());
                    }
                });
                default -> sender.sendMessage(Component.text(
                    "Usage: /season <status|start|end>", NamedTextColor.GRAY));
            }
            return true;
        }
        if (name.equals("laughtail")) {
            if (args.length == 0 || args[0].equalsIgnoreCase("status")) {
                if (!sender.hasPermission("laughtail.status")) {
                    sender.sendMessage(Component.text("No permission.", NamedTextColor.RED));
                    return true;
                }
                sender.sendMessage(Component.text("LaughTail " + getPluginMeta().getVersion(),
                    NamedTextColor.GOLD));
                sender.sendMessage(Component.text("  rules version: " + rulesVersion, NamedTextColor.GRAY));
                sender.sendMessage(Component.text("  worlds and Section 7.2 rules:", NamedTextColor.GRAY));
                for (String line : worldRules.describe().split("\n")) {
                    if (!line.isBlank()) sender.sendMessage(Component.text(line, NamedTextColor.DARK_GRAY));
                }
                sender.sendMessage(Component.text("  database: "
                    + (database.isHealthy() ? "reachable" : "NOT REACHABLE"),
                    database.isHealthy() ? NamedTextColor.GREEN : NamedTextColor.RED));
                getServer().getScheduler().runTaskAsynchronously(this, () -> {
                    String line;
                    try {
                        line = "  players recorded: " + database.countPlayers()
                             + "   combat events: " + database.countCombatEvents()
                             + "   anti-farm config: "
                             + (combatTracker.isPrivateConfigLoaded() ? "private.yml" : "PLACEHOLDERS")
                             + "   stat flushes pending: " + statsTracker.pendingCount();
                    } catch (SQLException ex) {
                        line = "  players recorded: query failed - " + ex.getMessage();
                    }
                    final String out = line;
                    getServer().getScheduler().runTask(this, () ->
                        sender.sendMessage(Component.text(out, NamedTextColor.GRAY)));
                });
                return true;
            }
            if (args[0].equalsIgnoreCase("rating")) {
                if (!sender.hasPermission("laughtail.status")) {
                    sender.sendMessage(Component.text("No permission.", NamedTextColor.RED));
                    return true;
                }
                // Appendix B asks for five invariants to be asserted in tests. Running them
                // through a command rather than a test harness is deliberate: it means the
                // maths can be re-verified on the live server after any config change to the
                // tier thresholds, which 9.3 says will be re-set from measurement after the
                // first season.
                java.util.List<String> fails = Rating.selfTest();
                sender.sendMessage(Component.text("Rating engine - Appendix B with D-0031 rulings",
                    NamedTextColor.GOLD));
                for (String l : Rating.examples()) {
                    sender.sendMessage(Component.text("  " + l, NamedTextColor.GRAY));
                }
                if (fails.isEmpty()) {
                    sender.sendMessage(Component.text(
                        "  INVARIANTS: all pass (5 from Appendix B, plus P11, P12, P13, repeat curve)",
                        NamedTextColor.GREEN));
                } else {
                    sender.sendMessage(Component.text("  INVARIANTS FAILED:", NamedTextColor.RED));
                    for (String l : fails) {
                        sender.sendMessage(Component.text("    " + l, NamedTextColor.RED));
                    }
                }
                return true;
            }            if (args[0].equalsIgnoreCase("reload")) {
                if (!sender.hasPermission("laughtail.reload")) {
                    sender.sendMessage(Component.text("No permission.", NamedTextColor.RED));
                    return true;
                }
                reloadConfig();
                loadSettings();
                getServer().getScheduler().runTaskAsynchronously(this, () -> database.checkConnectivity());
                sender.sendMessage(Component.text(
                    "LaughTail config reloaded. Rules version " + rulesVersion + ".",
                    NamedTextColor.GREEN));
                sender.sendMessage(Component.text(
                    "This is the reload to use - never vanilla /reload (never-break rule 7).",
                    NamedTextColor.DARK_GRAY));
                return true;
            }
            sender.sendMessage(Component.text("Usage: /laughtail <status|reload>", NamedTextColor.GRAY));
            return true;
        }
        return false;
    }
}
